export type CountryName = (typeof countries)[number]["name"];

const flagByCountry = new Map<string, string>(
  countries.map((country) => [country.name, country.flag]),
);

/** La bandera de un país, o `null` si el nombre no está en el catálogo. */
export function countryFlag(name: string | null | undefined) {
  return name ? (flagByCountry.get(name) ?? null) : null;
}

export function isCountryName(value: string): value is CountryName {
  return flagByCountry.has(value);
}
